{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "female"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Right lateral epicondylitis"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "bodySite": {
          "text": "Right lateral elbow"
        },
        "note": [
          {
            "text": "Chronic and work-aggravated. History and examination typical; no red flags, trauma, systemic or neurological symptoms. Previously assessed approximately 3 months ago as likely tennis elbow. Non-adherent to the previous conservative plan."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Right elbow pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Outer right elbow pain for approximately 9–10 months; intermittent and persisting, worse over the last 2–3 months. Local lateral elbow ache with sharp pain during lifting and gripping."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Right elbow pain aggravating and relieving factors"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Worse with scanning groceries, lifting bags, pouring a kettle and gripping the steering wheel, especially with the forearm pronated. Better with rest and as-needed ibuprofen."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Nocturnal elbow pain and sleep disturbance"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Occasional night pain when rolling onto the right side; wakes a few times per week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Morning stiffness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild morning stiffness that settles quickly; denies morning stiffness lasting more than 30 minutes."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Reported grip impairment"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Subjectively reduced grip; occasionally drops heavier items. Denies true weakness other than pain-limited function."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Associated elbow symptoms and injury history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No trauma, locking, giving way, redness, warmth or obvious swelling. No previous elbow problems reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Adherence to previous conservative treatment"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Admits poor adherence to the previous plan: keeps forgetting tablets and did not book physiotherapy because of irregular work and cost. Forgot regular ibuprofen use and ran out approximately 2 weeks ago."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Occupation and work-related functional impact"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Casual supermarket checkout operator working 3–4 shifts per week. Pain increases during long, busy shifts, requiring swapping hands and brief breaks."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Daily activity impact"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Avoids heavy housework and gardening; activities of daily living remain okay."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Reported chronic medical history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No significant chronic diagnoses reported; no inflammatory arthritis features."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Smoking status"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Non-smoker."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Alcohol consumption"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "1–2 standard drinks per week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Living circumstances"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Lives with partner and two school-aged children."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Barriers to accessing care"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Irregular shifts make appointments difficult to plan; cost is a barrier to physiotherapy. Patient remains hesitant about physiotherapy because of time and cost and is noncommittal about an assessment. Tends to forget appointments."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
